export function freshSave(){return {version:1,coins:0,best:0,selected:0,unlocked:[0],scores:[],stock:{},permanent:{},equipped:[],missionIndex:[0,40,80],missionProgress:{},completed:[],totals:{},settings:{music:true,sound:true,volume:.45,shake:true},runs:0};}
export function normalizeSave(input){const d=freshSave(); if(!input||input.version!==1)return d; const s={...d,...input};s.coins=Math.max(0,Number(s.coins)||0);s.unlocked=[...new Set([0,...(Array.isArray(s.unlocked)?s.unlocked:[]).filter(n=>Number.isInteger(n)&&n>=0&&n<10)])];if(!s.unlocked.includes(s.selected))s.selected=0;s.settings={...d.settings,...s.settings};s.settings.volume=Math.max(0,Math.min(1,Number(s.settings.volume)||0));s.best=Math.max(0,Number(s.best)||0);s.runs=Math.max(0,Number(s.runs)||0);for(const key of ['stock','permanent','totals','missionProgress'])if(!s[key]||typeof s[key]!=='object')s[key]={};s.scores=Array.isArray(s.scores)?s.scores.slice(0,10):[];s.equipped=Array.isArray(s.equipped)?s.equipped:[];s.completed=Array.isArray(s.completed)?s.completed:[];s.missionIndex=Array.isArray(s.missionIndex)&&s.missionIndex.length===3?s.missionIndex:d.missionIndex;return s;}
export function buyWeapon(save,id){const w=WEAPONS[id];if(!w)return false;if(save.unlocked.includes(id)){save.selected=id;return true;}if(save.coins<w.cost)return false;save.coins-=w.cost;save.unlocked.push(id);save.selected=id;return true;}
export class World{
 constructor({weapon=0,seed=Date.now(),onEvent=()=>{},effects={}}={}){this.seed=seed>>>0;this.onEvent=onEvent;this.weapon=WEAPONS[weapon]||WEAPONS[0];this.effects=effects;this.t=0;this.distance=effects.headstart||0;this.scroll=0;this.speed=290;this.hp=100;this.coins=0;this.kills=0;this.shots=0;this.y=FLOOR;this.vy=0;this.jumps=0;this.gliding=false;this.grounded=true;this.jumpHeld=false;this.fireHeld=false;this.cooldown=0;this.invincible=0;this.flash=0;this.dead=false;this.deathTime=0;this.entities=[];this.bullets=[];this.enemyBullets=[];this.particles=[];this.spawnTimer=2.3;this.coinTimer=.8;this.powerTimer=15;this.nextBoss=Math.floor(this.distance/500)*500+500;this.boss=null;this.bossCount=0;this.counts={};this.near={};this.gap=null;this.shake=0;this.reviveUsed=false;this.glideDistance=0;this.lastMeter=Math.floor(this.distance);}
 rand(){this.seed=(Math.imul(1664525,this.seed)+1013904223)>>>0;return this.seed/4294967296;}
 event(type,amount=1,sub=0){this.counts[type]=(this.counts[type]||0)+amount;this.onEvent(type,amount,sub);}
 jump(){if(this.dead)return;if(this.weapon.id===8){this.vy=-400;this.jumpHeld=true;return;}if(this.jumps<2){this.vy=this.jumps===0?-620:-545;this.grounded=false;this.jumps++;this.gliding=false;this.event('jump',1,this.jumps);}else{this.gliding=true;this.jumpHeld=true;this.event('glide');}}
 releaseJump(){this.jumpHeld=false;this.gliding=false;}
 particle(x,y,color='#a23a37',n=12){for(let i=0;i<n;i++)this.particles.push({x,y,vx:(this.rand()-.5)*300,vy:-this.rand()*260,life:.4+this.rand()*.4,max:.8,color,size:2+this.rand()*4});}
 hurt(damage){if(this.dead||this.invincible>0)return;this.hp=Math.max(0,this.hp-damage/(this.effects.armor||1));this.invincible=1.25;this.flash=.15;this.shake=9;this.event('hit');if(this.hp<=0){if(this.effects.life&&!this.reviveUsed){this.hp=100;this.invincible=4;this.reviveUsed=true;this.event('revive');}else{this.dead=true;this.event('Died',1,Math.floor(this.distance));this.particle(PLAYER_X,this.y-40,'#124f81',22);}}}
 spawn(kind,id,x=1020,y){if(kind==='hazard'){const h=HAZARDS[id];this.entities.push({...h,type:kind,x,y:y??(h.air?FLOOR-100-this.rand()*140:FLOOR),maxHp:h.hp,age:0});}else if(kind==='enemy'){const jet=id===1;this.entities.push({type:kind,id,sprite:jet?'ENM_EnemyJet_Idle_01':'ENM_EnemyKnife_Idle_01',w:jet?88:70,h:jet?104:106,hp:jet?100:80,maxHp:jet?100:80,damage:25,x,y:y??(jet?FLOOR-90-this.rand()*170:FLOOR),baseY:y,age:0,shoot:1+this.rand()});}else if(kind==='coin'){this.entities.push({type:kind,id:0,x,y:y??FLOOR-45,w:26,h:26,age:0});}else this.entities.push({type:kind,id,x,y:y??FLOOR-85,w:44,h:44,age:0});}
 shoot(){const w=this.weapon;this.cooldown=w.rate;this.shots++;this.event('FireWeapon',1,w.id);const count=w.pellets||1;for(let i=0;i<count;i++){this.bullets.push({x:PLAYER_X+44,y:this.y-67,vx:w.speed,vy:count>1?(i-(count-1)/2)*100:0,life:w.range?w.range/w.speed:1.6,damage:w.damage*(this.effects.power||1),id:w.id,blast:w.blast||0,pierce:w.pierce,homing:w.homing,hit:new Set()});}this.event('shoot',1,w.id);}
 destroy(e,shot=true){if(e.dead)return;e.dead=true;this.particle(e.x,e.y-e.h/2,e.type==='enemy'?(this.effects.blood?'#a61d19':'#365f86'):'#b83f3b',this.effects.blood?26:14);if(shot){this.event(e.type==='enemy'?'KilledMovingEnemy':'DestroyedStaticHazard',1,e.id);if(e.type==='enemy')this.kills++;for(let i=0;i<(this.effects.blood&&e.type==='enemy'?6:3);i++)this.spawn('coin',0,e.x+(i-1)*25,e.y-40-i*15);}this.event('destroy',1,e.id);if(e.blast)this.explode(e.x,e.y-40,e.blast,120,e);}
 explode(x,y,r,damage,except){this.particle(x,y,'#eb7a24',25);this.shake=7;for(const e of this.entities){if(e===except||e.dead||!['hazard','enemy'].includes(e.type))continue;if(Math.hypot(e.x-x,e.y-e.h/2-y)<r){e.hp-=damage;if(e.hp<=0)this.destroy(e);}}if(this.boss&&Math.hypot(this.boss.x-x,this.boss.y-65-y)<r+50)this.damageBoss(damage);this.event('explosion');}
 damageBoss(d){if(!this.boss)return;this.boss.hp-=d;this.boss.flash=.1;if(this.boss.hp<=0){this.particle(this.boss.x,this.boss.y-60,'#9c2c25',45);this.boss=null;this.bossCount++;this.kills++;this.coins+=100;this.event('BossKill');this.event('bonus',100);this.event('bossEnd');}}
 update(dt){dt=Math.min(dt,.05);if(this.dead){this.deathTime+=dt;this.updateParticles(dt);return;}this.t+=dt;this.speed=Math.min(460,290+this.distance*.045);const move=this.speed*dt;this.scroll+=move;this.distance+=move/20;const meter=Math.floor(this.distance);if(meter>this.lastMeter){this.event('Ran1Meter',meter-this.lastMeter);this.lastMeter=meter;}this.invincible=Math.max(0,this.invincible-dt);this.flash=Math.max(0,this.flash-dt);this.shake=Math.max(0,this.shake-dt*32);this.cooldown-=dt;if(this.fireHeld&&this.cooldown<=0)this.shoot();
 if(this.weapon.id===8){this.vy+=(this.jumpHeld?-1600:900)*dt;this.vy=Math.max(-400,Math.min(400,this.vy));this.y+=this.vy*dt;if(this.y<145){this.y=145;this.vy=0;}if(this.y>=FLOOR){this.y=FLOOR;this.vy=0;}this.grounded=false;}else{let gravity=1550;if(this.gliding&&this.jumpHeld&&this.vy>0){gravity=100;this.vy=Math.min(this.vy,this.effects.glide?38:70);this.glideDistance+=move/20;const old=Math.floor(this.glideDistance-move/20);if(Math.floor(this.glideDistance)>old)this.event('Glide1Meter',Math.floor(this.glideDistance)-old);}this.vy+=gravity*dt;this.y+=this.vy*dt;this.grounded=false;if(this.y>=FLOOR){this.y=FLOOR;this.vy=0;this.jumps=0;this.gliding=false;this.grounded=true;}}
 if(!this.boss){this.spawnTimer-=dt;if(this.spawnTimer<=0){const difficulty=Math.min(6,Math.floor(this.distance/150));const r=this.rand();if(r<.28&&this.distance>70)this.spawn('enemy',this.rand()<.4?1:0);else this.spawn('hazard',Math.floor(this.rand()*Math.min(10,3+difficulty)));this.spawnTimer=1.35+this.rand()*1.25-Math.min(.4,this.distance/3000);}}
 this.coinTimer-=dt;if(this.coinTimer<=0){const high=this.rand()<.45;const base=FLOOR-(high?130:30);for(let i=0;i<6;i++)this.spawn('coin',0,1000+i*38,base-Math.sin(i/5*Math.PI)*55);this.coinTimer=3+this.rand()*2;}
 this.powerTimer-=dt;if(this.powerTimer<=0){this.spawn(this.rand()<.65?'health':'shield',0,1030,FLOOR-70-this.rand()*120);this.powerTimer=15+this.rand()*10;}
 if(!this.boss&&this.distance>=this.nextBoss){this.boss={x:1100,y:FLOOR,hp:1200+this.bossCount*300,maxHp:1200+this.bossCount*300,t:0,shoot:1.5,flash:0};this.nextBoss+=500;this.entities=this.entities.filter(e=>e.type==='coin');this.event('bossStart');}
 if(this.boss){const b=this.boss;b.t+=dt;b.flash=Math.max(0,b.flash-dt);b.x+=(760-b.x)*dt*1.1;b.y=FLOOR-12+Math.sin(b.t*1.5)*8;b.shoot-=dt;if(b.shoot<0){b.shoot=1.35-Math.min(.5,this.bossCount*.1);for(let i=0;i<3;i++)this.enemyBullets.push({x:b.x-75,y:b.y-75,vx:-390,vy:(i-1)*65,life:4,w:22,h:12});this.event('enemyShoot');}}
 for(const e of this.entities){e.age+=dt;e.x-=move;if(e.type==='enemy'){if(e.id===0)e.x-=dt*65;else{e.y+=Math.sin(e.age*3)*dt*28;e.shoot-=dt;if(e.shoot<=0){e.shoot=2.5;const angle=Math.atan2(this.y-65-(e.y-50),PLAYER_X-e.x);this.enemyBullets.push({x:e.x-25,y:e.y-50,vx:Math.cos(angle)*340,vy:Math.sin(angle)*340,life:4,w:18,h:12});}}}if(e.type==='coin'&&this.effects.magnet&&Math.abs(e.x-PLAYER_X)<240){e.x+=(PLAYER_X-e.x)*dt*8;e.y+=(this.y-55-e.y)*dt*8;}
 const pad=e.type==='coin'?20:8;const overlap=Math.abs(e.x-PLAYER_X)<e.w/2+22+pad&&e.y>this.y-102+pad&&e.y-e.h<this.y-8;
 if(overlap&&!e.dead){if(e.type==='coin'){e.dead=true;this.coins+=this.effects.doubleCoins?2:1;this.event('GotCoin');this.event('coin');}else if(e.type==='health'){e.dead=true;this.hp=Math.min(100,this.hp+(this.effects.fullHealth?100:35));this.event('GotHP');this.event('health');}else if(e.type==='shield'){e.dead=true;this.invincible=this.effects.longShield?15:8;this.event('shield');}else{this.hurt(e.damage);if(e.type==='hazard')this.event('SmashIntoStaticHazard',1,e.id);e.dead=true;this.particle(e.x,e.y-e.h/2);}}
 if(e.x<PLAYER_X-50&&!e.passed&&!e.dead&&e.type==='hazard'){e.passed=true;if(Math.abs(this.y-(e.y-e.h))<125)this.event('NearMissStaticHazard',1,e.id);}}
 for(const b of this.bullets){b.life-=dt;if(b.homing){const target=this.boss||this.entities.find(e=>!e.dead&&e.hp>0&&e.x>b.x);if(target){b.vy+=(Math.sign(target.y-(target.h||120)/2-b.y)*520-b.vy)*dt*4;}}b.x+=b.vx*dt;b.y+=b.vy*dt;if(b.id===4)b.vy+=250*dt;for(const e of this.entities){if(e.dead||!e.hp||b.hit.has(e)||b.life<=0)continue;const radius=b.id===7?35:b.id===9?30:6;if(Math.abs(b.x-e.x)<e.w/2+radius&&b.y>e.y-e.h-radius&&b.y<e.y+radius){e.hp-=b.damage;b.hit.add(e);this.particle(b.x,b.y,'#4d7693',4);if(e.hp<=0)this.destroy(e);if(b.blast)this.explode(b.x,b.y,b.blast,b.damage*.6,e);if(!b.pierce)b.life=0;}}
 const boss=this.boss;if(boss&&b.life>0&&!b.hit.has(boss)&&Math.abs(b.x-boss.x)<80&&b.y>boss.y-155&&b.y<boss.y){b.hit.add(boss);this.damageBoss(b.damage);if(!b.pierce)b.life=0;}
 for(const eb of this.enemyBullets){if(eb.life>0&&b.life>0&&Math.abs(eb.x-b.x)<18&&Math.abs(eb.y-b.y)<16){eb.life=0;if(!b.pierce)b.life=0;this.particle(eb.x,eb.y,'#d38b31',5);this.event('DuarteCompanhia');}}}
 for(const b of this.enemyBullets){b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;if(Math.abs(b.x-PLAYER_X)<24&&b.y>this.y-100&&b.y<this.y-5&&b.life>0){b.life=0;this.hurt(20);}}
 this.entities=this.entities.filter(e=>!e.dead&&e.x>-140);this.bullets=this.bullets.filter(b=>b.life>0&&b.x<1250&&b.y<700);this.enemyBullets=this.enemyBullets.filter(b=>b.life>0&&b.x>-100);this.updateParticles(dt);}
 updateParticles(dt){for(const p of this.particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=550*dt;p.life-=dt;}this.particles=this.particles.filter(p=>p.life>0);}
}
